    if (key === shownKey) return;
    shownKey = key;
    items = picked;
    try { localStorage.setItem('tess:dialItems', JSON.stringify(items.map(({ uri, title, subtitle, img, kind, source, reason }) => ({ uri, title, subtitle, img, kind, source, reason })))); } catch {}
